set -eu
python3 - <<'PY'
import subprocess,sys,json,pathlib,os,time
def run(args,timeout=90):
 return subprocess.run(args,capture_output=True,text=True,timeout=timeout)
def require(args,timeout=15):
 p=run(args,timeout)
 if p.returncode:raise RuntimeError('PREFLIGHT_FAILED')
 return p.stdout.strip()
name='deploy-gaybbs-1'
active=json.loads(require(['docker','inspect',name]))[0]
if not active['State']['Running']:sys.exit(61)
before=active['Image']
tag='gace-tgtumbler-gaybbs:local'
candidate='gace-tgtumbler-gaybbs:search-color-5a93de6'
backup='gace-tgtumbler-gaybbs:before-search-colors-20261114'
if require(['docker','image','inspect',tag,'--format','{{.Id}}'])!=before:sys.exit(62)
newid=require(['docker','image','inspect',candidate,'--format','{{.Id}}'])
if before==newid:sys.exit(0)
raw=active['Config']['Labels']['com.docker.compose.project.config_files']
files=[x.strip() for x in raw.split(',') if x.strip()]
if len(files)!=2 or not pathlib.Path(files[0]).is_file():sys.exit(63)
basepath=pathlib.Path(files[0]).resolve()
if not basepath.is_relative_to(pathlib.Path.home()):sys.exit(64)
args=['docker','compose','-f',str(basepath),'-p','deploy']
current_hash=active['Config']['Labels']['com.docker.compose.config-hash']
if current_hash not in require(args+['config','--hash','gaybbs']):sys.exit(65)
config=json.loads(require(args+['config','--format','json']))
mounts={m['Destination']:pathlib.Path(m['Source']) for m in active.get('Mounts',[]) if m['Type']=='bind'}
pairs=[]
for key in ('bot_token','db_password'):
 desired=pathlib.Path(config['secrets'][key]['file'])
 source=mounts.get('/run/secrets/'+key)
 if source is None or not source.is_file():sys.exit(66)
 if desired.parent.resolve()!= (basepath.parent/'secrets').resolve():sys.exit(67)
 if not desired.is_relative_to(pathlib.Path.home()):sys.exit(68)
 if desired.exists():
  if not desired.samefile(source):sys.exit(69)
 else:
  if desired.is_symlink():sys.exit(70)
  pairs.append((desired,source.resolve()))
for desired,source in pairs:
 desired.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
 desired.symlink_to(source)
if run(args+['config','-q'],25).returncode:sys.exit(71)
if run(['docker','tag',before,backup],15).returncode:sys.exit(72)
if run(['docker','tag',candidate,tag],15).returncode:sys.exit(73)
p=run(args+['up','-d','--no-deps','gaybbs'],90)
if p.returncode:
 run(['docker','tag',backup,tag],15)
 restored=run(args+['up','-d','--no-deps','gaybbs'],90)
 if restored.returncode:sys.exit(80)
 sys.exit(81)
time.sleep(7)
p=run(['docker','inspect',name],20)
if p.returncode:sys.exit(82)
after=json.loads(p.stdout)[0]
if after['Image']!=newid or not after['State']['Running']:
 run(['docker','tag',backup,tag],15)
 run(args+['up','-d','--no-deps','gaybbs'],90)
 sys.exit(83)
sys.exit(0)
